import {PERSONAL_KEY,DEFAULT_PERSONAL,validatePersonal,calendarDays} from '../core/personalization.js';
import {validateWidget} from '../core/appearance.js';
import {createHistory} from '../core/editor-history.js';
import {dateKey} from '../core/model.js';
import {scheduleClock} from '../core/sessions.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readPersonal(){try{return validatePersonal(JSON.parse(localStorage.getItem(PERSONAL_KEY)||'{}'));}catch{return validatePersonal(DEFAULT_PERSONAL);}}
export function setupStudio({get,notify,openSheet,closeSheets,sync}){
 let state=readPersonal(),editing=false,drag=null,selected=null,rangeBefore=null,widgets=[],previewWidget=null;
 const history=createHistory(),fab=$('#fab'),fabMarkup=fab.innerHTML,fabClick=fab.onclick;
 function finishEditing(){if(!editing)return false;editing=false;selected=null;refresh();return true;}
 fab.onclick=()=>{if(!finishEditing())fabClick();};
 const board=document.createElement('div'),layer=document.createElement('div');board.id='decoration-board';layer.id='decoration-layer';const grid=$('#timetable');grid.before(board);board.append(grid,layer);$('#week-view').prepend($('#fun-widget'));board.before($('#decoration-tools'));
 function save(next,record=true,before=state){try{next=validatePersonal(next);localStorage.setItem(PERSONAL_KEY,JSON.stringify(next));if(record)history.push(before);state=next;refresh();sync();return true;}catch(e){notify(e.message);return false;}}
 function widgetData(){const now=new Date(),{courses,settings}=get(),clock=scheduleClock(courses,settings,now),current=clock.current.length>0,c=current?clock.current[0]:clock.next[0];return c?{title:(current?'正在上课 · ':clock.onBreak?'课间 · 下一节 ':'下一节 · ')+c.name,detail:c.date.slice(5)+' 第'+c.period+'节 '+c.time+' · '+(c.location||'地点待定')}:{title:'留一点时间，给喜欢的事',detail:'未来7天没有课程'};}
 function widgetHTML(w=state.widget){const now=new Date(),d=widgetData();return `<div class="fun-card style-${w.style}" style="--widget-accent:${w.accent};--widget-alpha:${w.opacity/100}"><div class="record-art" aria-hidden="true">♫</div><div class="fun-card-body"><small>${w.content==='course'?'我的课间':w.content==='date'?'TODAY':'JUST FOR YOU'}</small><strong>${E(w.content==='course'?d.title:w.content==='date'?now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):w.quote)}</strong><span>${E(w.content==='course'?d.detail:now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}))}</span></div></div>`;}
 const transform=item=>`translate(-${item.x}%,-${item.y}%) rotate(${item.rotation}deg) scale(${item.scale})`;
 function refreshTools(){const item=state.items.find(i=>i.id===selected);$('#decoration-tools').hidden=!editing;$('#decoration-selected').textContent=item?(item.locked?'🔒 ':'')+item.text:'点一个挂件进行编辑';$('#decoration-undo').disabled=!history.canUndo;$('#decoration-redo').disabled=!history.canRedo;$('#decoration-controls').hidden=!item;if(item){$('#decoration-scale').value=item.scale;$('#decoration-rotation').value=item.rotation;$('#decoration-scale-value').textContent=Math.round(item.scale*100)+'%';$('#decoration-rotation-value').textContent=item.rotation+'°';$('#decoration-lock').textContent=item.locked?'解锁位置':'锁定位置';}}
 function renderLayer(){layer.innerHTML=state.items.map(item=>{const days=item.type==='countdown'?calendarDays(item.date):0,text=item.type==='countdown'?`${item.text} · ${days>0?'还有 '+days+' 天':days===0?'就是今天':'已过 '+Math.abs(days)+' 天'}`:item.text;return `<button type="button" class="decoration decoration-${item.type} ${selected===item.id?'selected':''} ${item.locked?'locked':''}" data-decoration="${E(item.id)}" style="left:${item.x}%;top:${item.y}%;transform:${transform(item)};z-index:${item.z}" aria-label="${E(text)}${editing?'，编辑挂件':''}">${E(text)}${item.type==='link'?' ↗':''}</button>`;}).join('');}
 function refresh(){if(drag)return;fab.innerHTML=editing?'✓':fabMarkup;fab.setAttribute('aria-label',editing?'完成挂件摆放':'添加个人安排');$('#widget-preview').innerHTML=widgetHTML(previewWidget||state.widget);$('#fun-widget').innerHTML=widgetHTML();$('#fun-widget').hidden=!state.widget.showInApp;layer.hidden=!state.visible;layer.classList.toggle('editing',editing);board.classList.toggle('editing',editing);$('#decoration-edit').textContent=editing?'完成摆放':'拖动摆放';$('#decoration-visibility').textContent=state.visible?'隐藏全部挂件':'显示全部挂件';renderLayer();refreshTools();$('#decoration-list').innerHTML=state.items.length?state.items.map(item=>`<div class="decoration-list-row"><button type="button" class="decoration-list-select" data-select-decoration="${E(item.id)}">${item.locked?'🔒 ':''}${E(item.text)}</button><button type="button" data-remove-decoration="${E(item.id)}" aria-label="删除${E(item.text)}">删除</button></div>`).join(''):'<p class="sheet-tip">先加一个贴纸，或者写一句喜欢的话。</p>';}
 layer.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-decoration]');if(!el||!editing)return;const item=state.items.find(i=>i.id===el.dataset.decoration);selected=item.id;refreshTools();layer.querySelectorAll('.decoration').forEach(x=>x.classList.toggle('selected',x===el));if(item.locked)return;event.preventDefault();drag={id:item.id,pointer:event.pointerId,px:event.clientX,py:event.clientY,el,startX:item.x,startY:item.y,x:item.x,y:item.y};el.setPointerCapture(event.pointerId);});
 layer.addEventListener('pointermove',event=>{if(!drag||drag.pointer!==event.pointerId)return;event.preventDefault();const r=board.getBoundingClientRect(),d=drag;d.x=Math.max(0,Math.min(100,d.startX+(event.clientX-d.px)/Math.max(1,r.width-d.el.offsetWidth)*100));d.y=Math.max(0,Math.min(100,d.startY+(event.clientY-d.py)/Math.max(1,r.height-d.el.offsetHeight)*100));let snapX=false;if($('#decoration-snap').checked){for(const n of [0,25,50,75,100])if(Math.abs(d.x-n)<2){d.x=n;snapX=n===50;break;}const n=Math.round(d.y/100*12)/12*100;if(Math.abs(d.y-n)<1)d.y=n;}board.classList.toggle('snap-x',snapX);const item={...state.items.find(i=>i.id===d.id),x:d.x,y:d.y};Object.assign(d.el.style,{left:d.x+'%',top:d.y+'%',transform:transform(item)});});
 for(const event of ['pointerup','pointercancel'])layer.addEventListener(event,e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag;drag=null;board.classList.remove('snap-x');if(event==='pointerup'&&(d.x!==d.startX||d.y!==d.startY))save({...state,items:state.items.map(i=>i.id===d.id?{...i,x:d.x,y:d.y}:i)});else refresh();});
 layer.addEventListener('click',event=>{if(editing)return;const el=event.target.closest('[data-decoration]'),item=state.items.find(i=>i.id===el?.dataset.decoration);if(!item)return;if(item.type==='link')window.open(item.url,'_blank','noopener,noreferrer');else if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{scale:1},{scale:1.16,rotate:'-8deg'},{scale:1}],{duration:350});});
 $('#decoration-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements,type=f.type.value,text=f.text.value.trim()||(type==='sticker'?'✨':'');if(save({...state,visible:true,items:[...state.items,{id:crypto.randomUUID(),type,text,date:f.date.value,url:f.url.value,x:state.items.length%2===0?70:12,y:Math.min(86,38+Math.floor(state.items.length/2)*8),z:Math.min(99,state.items.length+1)}]})){f.text.value='';notify('已添加，可拖动、缩放或旋转');}};
 $('#decoration-type').onchange=()=>{const type=$('#decoration-type').value;$('#decoration-date-label').hidden=type!=='countdown';$('#decoration-url-label').hidden=type!=='link';};
 $('#sticker-options').onclick=e=>{const emoji=e.target.closest('[data-sticker]')?.dataset.sticker;if(emoji){$('#decoration-type').value='sticker';$('#decoration-type').onchange();$('#decoration-form').elements.text.value=emoji;}};
 $('#decoration-list').onclick=e=>{const id=e.target.closest('[data-remove-decoration]')?.dataset.removeDecoration;if(id){save({...state,items:state.items.filter(i=>i.id!==id)});notify('已删除，可在摆放工具中撤销');}const select=e.target.closest('[data-select-decoration]')?.dataset.selectDecoration;if(select){selected=select;editing=true;save({...state,visible:true},false);closeSheets();$('#decoration-tools').scrollIntoView({block:'nearest'});}};
 $('#decoration-visibility').onclick=()=>save({...state,visible:!state.visible});$('#decoration-edit').onclick=()=>{editing=!editing;selected=state.items[0]?.id||null;save({...state,visible:true},false);closeSheets();if(editing){$('#decoration-tools').scrollIntoView({block:'nearest'});notify('选中挂件编辑；右下角 ✓ 完成摆放');}};
 $('#decoration-undo').onclick=()=>{const value=history.undo(state);if(value)save(value,false);};$('#decoration-redo').onclick=()=>{const value=history.redo(state);if(value)save(value,false);};
 const changeItem=fn=>{if(selected)save({...state,items:state.items.map(i=>i.id===selected?fn(i):i)});};$('#decoration-lock').onclick=()=>changeItem(i=>({...i,locked:!i.locked}));
 for(const [id,delta]of [['front',1],['back',-1]])$('#decoration-'+id).onclick=()=>{const sorted=[...state.items].sort((a,b)=>a.z-b.z),index=sorted.findIndex(i=>i.id===selected),target=Math.max(0,Math.min(sorted.length-1,index+delta));if(index<0||target===index)return;[sorted[index],sorted[target]]=[sorted[target],sorted[index]];save({...state,items:sorted.map((i,z)=>({...i,z}))});};
 for(const name of ['scale','rotation']){const input=$('#decoration-'+name);input.oninput=()=>{if(!rangeBefore)rangeBefore=JSON.parse(JSON.stringify(state));state=validatePersonal({...state,items:state.items.map(i=>i.id===selected?{...i,[name]:Number(input.value)}:i)});renderLayer();refreshTools();};input.onchange=()=>{if(rangeBefore){const before=rangeBefore;rangeBefore=null;save(state,true,before);}};}
 function nativeWidgets(){try{return JSON.parse(window.CourseCompass?.getWidgetConfigs?.()||'[]');}catch{return [];}}
 function fillWidget(w){const f=$('#widget-form').elements;w=validateWidget(w);f.style.value=w.style;f.content.value=w.content;f.quote.value=w.quote;f.showInApp.checked=state.widget.showInApp;f.accent.value=w.accent;f.opacity.value=w.opacity;previewWidget=w;$('#widget-preview').innerHTML=widgetHTML(w);}
 function loadWidgets(){widgets=nativeWidgets();$('#widget-target').innerHTML='<option value="0">应用内 / 新组件默认样式</option>'+widgets.map((w,i)=>`<option value="${w.id}">桌面组件 ${i+1} · #${w.id}</option>`).join('');let presets=[];try{presets=JSON.parse(localStorage.getItem('course-compass.widget-presets.v1')||'[]');}catch{}$('#widget-preset').innerHTML='<option value="">从备份的组件样式复制（可选）</option>'+presets.map((w,i)=>`<option value="${i}">组件预设 ${i+1} · ${E(w.style)}</option>`).join('');$('#widget-preset').onchange=e=>{if(e.target.value!=='')fillWidget(presets[Number(e.target.value)]);};}
 $('#widget-target').onchange=e=>fillWidget(Number(e.target.value)?widgets.find(w=>w.id===Number(e.target.value))||state.widget:state.widget);
 $('#widget-form').oninput=()=>{const f=$('#widget-form').elements;previewWidget=validateWidget({style:f.style.value,content:f.content.value,quote:f.quote.value,accent:f.accent.value,opacity:f.opacity.value});$('#widget-preview').innerHTML=widgetHTML(previewWidget);};
 $('#widget-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements,w=validateWidget({style:f.style.value,content:f.content.value,quote:f.quote.value,showInApp:f.showInApp.checked,accent:f.accent.value,opacity:f.opacity.value}),id=Number($('#widget-target').value);if(id){if(!window.CourseCompass?.setWidgetConfig?.(id,JSON.stringify(w))){notify('此桌面组件已不存在，请重新选择');return;}widgets=nativeWidgets();localStorage.setItem('course-compass.widget-presets.v1',JSON.stringify(widgets));notify('此桌面组件已单独更新');}else if(save({...state,widget:w}))notify('默认样式已保存，已有独立设置的组件保持原样');};
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='decorations'){refresh();openSheet('#decorations-sheet');}if(action==='companion'){loadWidgets();fillWidget(state.widget);refresh();}});
 window.openWidgetEditor=id=>{loadWidgets();$('#widget-target').value=String(id);fillWidget(widgets.find(w=>w.id===id)||state.widget);openSheet('#companion-sheet');};
 window.addEventListener('resize',()=>{drag=null;refresh();});setInterval(()=>{if(!document.hidden)refresh();},60000);refresh();return {refresh,refreshClock:()=>{if(!editing){for(const [id,w] of [['#widget-preview',previewWidget||state.widget],['#fun-widget',state.widget]]){const element=$(id),html=widgetHTML(w);if(element.dataset.clockHtml!==html){element.innerHTML=html;element.dataset.clockHtml=html;}}}},finishEditing,reload(){state=readPersonal();history.clear();refresh();sync();}};
}
